INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6b2-762e-982d-9a230904d542'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Write x^2 - 10x + 7 in the form (x - a)^2 + b.', '(x - 5)^2 - 18', 'Complete the square: x^2 - 10x + 7 = (x^2 - 10x + 25) - 25 + 7 = (x - 5)^2 - 18.', 'Easy', '{"tags":"algebra,quadratics,completing-the-square","subtopic":"completing the square","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.842Z'::timestamptz, '2026-07-26T12:42:25.842Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b681-7ab4-b97f-c92fe8c20252'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A shirt costs £14.75 in one country. In another country, the same shirt costs $21.99. If the exchange rate is $1 = £0.73, calculate how much more the second price is than the first, in pounds.', '£1.30', 'Convert $21.99 to pounds: 21.99 × 0.73 = 16.0527. Subtract 14.75: 16.0527 - 14.75 = 1.3027. To the nearest penny, the difference is £1.30.', 'Easy', '{"tags":"ratio,exchange-rates,money","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.793Z'::timestamptz, '2026-07-26T12:42:25.793Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b688-7ff9-971b-1d6c0e1ef6df'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Simplify 6a^5b^2 ÷ 3a^2b.', '2a^3b', 'Divide coefficients: 6 ÷ 3 = 2. Subtract the powers: a^(5-2) = a^3 and b^(2-1) = b. So the simplified form is 2a^3b.', 'Easy', '{"tags":"algebra,indices,simplification","subtopic":"indices","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.800Z'::timestamptz, '2026-07-26T12:42:25.800Z'::timestamptz) ON CONFLICT (id) DO NOTHING;